    int public ans = 0;
    function loop(int val) public pure returns (int) {
        int a = val;
        for (a; a < 5; a++) {
        }
        while (a > 0) {
            a = a + 1;
            return a;
        }
        do {
            a = a - 1;
        } while (a <= 5);
        return a;
    }
}
